-- V38: imperative (Imperativus) conjugation lesson: rename + seed paradigms.
--
-- The imperative topic (code 'imperative', L4) is renamed to the Latin-namespace
-- 'imperativus' and releveled to L2, mirroring the V34 renaming of the other
-- verb lessons. Prerequisite edges and quest bindings reference topic_id (UUID),
-- not code, so renaming the code does not break them. display_order is appended
-- to the end of the target learning level (tie-break within a level, curriculum.md §2).
--
-- Then conjugation paradigms (person x number = 9 per verb, 10 verbs) are seeded
-- for the imperativus lesson. Source: etcetera/grammar/sanskrit_verbs_imperative.json.
-- Served by ConjugationParadigmService as an index-based carousel (one verb per page).

UPDATE curriculum.topic
SET code = 'imperativus',
    title_ru = 'Повелительное наклонение',
    title_en = 'Imperative mood',
    learning_level = 'L2',
    display_order = (SELECT COALESCE(MAX(display_order), 0) + 1
                     FROM curriculum.topic WHERE learning_level = 'L2')
WHERE code = 'imperative';

